<?php
require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);requireRole($user,['Administrator']);$q=is_string($_GET['q']??null)?$_GET['q']:'';$role=is_string($_GET['role']??null)?$_GET['role']:'';$status=is_string($_GET['status']??null)?$_GET['status']:'';$rows=searchUsers($pdo,$q,$role,$status);pageStart('Manage Users'); ?>
<form method="get" class="mb-3"><input name="q" placeholder="Search name or email" value="<?=escapeHtml($q)?>"><select name="role"><option value="">All roles</option><?php foreach(['Student','Tutor','Administrator'] as $v):?><option <?=$role===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['Active','Inactive'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Search</button></form>
<table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(['full_name','email','role','status'] as $k):?><td><?=escapeHtml($r[$k])?></td><?php endforeach;?><td><a href="manage-user.php?id=<?=(int)$r['user_id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows)echo '<p>No matching accounts.</p>';pageEnd(); ?>
